package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Normalizes the create-owner address: trims and collapses whitespace, upper-cases and expands
 * common street-type abbreviations ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
 * Mutates the published request in place so later steps store and return the normalized value, and
 * so household duplicate detection and the shared household id compare the normalized form.
 *
 * <p>{@link ValidateOwnerFields} has already rejected an address that is blank after normalization,
 * so at this point the value normalizes to a non-empty string.
 */
public class NormalizeOwnerAddress {

    public void service(@Val OwnerFieldsDto request) {
        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
    }
}
===== AddressNormalizer =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

/**
 * Canonicalises a raw postal address entry into its normalized form.
 *
 * <p>Rules: trim leading/trailing whitespace, collapse internal runs of whitespace to a single
 * space, upper-case, and expand common street-type abbreviations token-by-token
 * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). An address that is empty or
 * whitespace-only normalizes to the empty string.
 *
 * <p>The conversion is idempotent — feeding an already-normalized value back in returns it
 * unchanged — so it can normalize both incoming requests and already-stored values for
 * comparison (household duplicate detection and the shared household id).
 */
final class AddressNormalizer {

    private AddressNormalizer() {
    }

    /**
     * @param raw the raw address text (may be {@code null})
     * @return the normalized address, or {@code ""} when {@code raw} is blank after normalization
     */
    static String normalize(String raw) {
        if (raw == null) {
            return "";
        }
        String collapsed = raw.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder result = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                result.append(' ');
            }
            result.append(expand(tokens[i]));
        }
        return result.toString();
    }

    private static String expand(String token) {
        switch (token) {
            case "ST":
                return "STREET";
            case "RD":
                return "ROAD";
            case "AVE":
                return "AVENUE";
            default:
                return token;
        }
    }
}
===== CheckOwnerCityCapacity =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.OwnerCityFullException;

/**
 * Rejects a create-owner request whose city already contains {@value #CAPACITY} or more owners
 * with a 409. The city is compared case-insensitively, matching the per-city counting used by
 * {@code AssignOwnerCustomerCode}. Runs before the owner is saved, so the count reflects
 * existing owners only.
 */
public class CheckOwnerCityCapacity {

    /** A city is full once it already holds this many owners. */
    static final int CAPACITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws OwnerCityFullException {
        String city = request.getCity();
        long count = ownerRepository.findAll().stream()
                .map(Owner::getCity)
                .filter(existing -> city == null ? existing == null : city.equalsIgnoreCase(existing))
                .count();
        if (count >= CAPACITY) {
            throw new OwnerCityFullException(city, (int) count);
        }
    }
}

